package com.hmdp.ai.runtime.knowledge.chunking;
import com.hmdp.ai.domain.knowledge.ChunkFragment;import com.hmdp.ai.domain.knowledge.ChunkingPolicy;import com.hmdp.ai.domain.knowledge.parsing.*;import org.springframework.stereotype.Component;import java.util.*;import java.util.stream.Collectors;
@Component public class SpreadsheetRowChunkingStrategy implements ChunkingStrategy {public String code(){return "SPREADSHEET_ROW";}public List<ChunkFragment> chunk(ParsedDocument d,ChunkingPolicy p){List<ChunkFragment>out=new ArrayList<>();for(ParsedTable table:d.getTables()){Map<Integer,List<ParsedCell>>rows=table.getCells().stream().collect(Collectors.groupingBy(ParsedCell::getRow,TreeMap::new,Collectors.toList()));for(Map.Entry<Integer,List<ParsedCell>>row:rows.entrySet()){row.getValue().sort(Comparator.comparingInt(ParsedCell::getColumn));String text=row.getValue().stream().map(c->c.getAddress()+"="+c.getValue()).collect(Collectors.joining(" | "));int min=row.getValue().stream().mapToInt(ParsedCell::getColumn).min().orElse(0),max=row.getValue().stream().mapToInt(ParsedCell::getColumn).max().orElse(0);out.add(new ChunkFragment(text,table.getPage(),table.getName(),null,table.getName(),row.getKey(),row.getKey(),min,max,null,null));}}return out;}}
